def page(fn,title,sub,qs,note):
    out=[]
    for i,(stem,opts,ans,why,sure) in enumerate(qs,1):
        m=len(ans)>1 or 'select all' in stem.lower()
        ob=''.join(f'<button class="opt">{chr(65+j)}. {E(o)}</button>' for j,o in enumerate(opts))
        fl='' if sure else '<div class="flag">⚠️ Not 100% sure. See the note.</div>'
        out.append(f'<div class="q" data-a="{json.dumps(ans)}" data-m="{int(m)}"><h3><span>Q{i}</span>{E(stem)}</h3>{ob}{"<button class=chk>Check ✓</button>" if m else ""}<div class="why">✅ <b>{", ".join(chr(65+a) for a in ans)}</b>{" · "+E(why) if why else ""}{fl}</div></div>')
    open(fn,'w').write(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)}</title><style>{CSS}</style></head><body><div class="wrap"><a class="back" href="systems-lec-exam4.html?v={V}">← Back to Exam 4</a><div class="hero"><h1>{E(title)}</h1><p>{E(sub)}</p></div><div class="note">{note}</div><div class="bar"><button id="shuf">🎲 Shuffle</button><button id="miss">🔁 Misses only</button><button id="all">↺ Show all</button><span class="score" id="sc"></span></div><div id="qs">{"".join(out)}</div></div><script>{JS}</script>{SW}</body></html>')
NOTE='Tap an answer to check it. Select-all questions need ✓ Check. <b>No official key:</b> answers were worked out from Basel\'s slides and transcripts. ⚠️ = less sure · 🟠 = sources disagree · 🔁 = asked on both years.'
page('systems-lec4-old2025.html','📝 Basel Old Exam · 2025','Renal · 70 Q (60 renal + 10 immune) · scantron · 90 min',X25,NOTE+' Q61–70 are immune/lymphoid, not renal.')
page('systems-lec4-old2024.html','📝 Basel Old Exam · 2024','Renal · 57 Q · scantron · 90 min',X24,NOTE)
